class Solution {
public:
    std::string removeDigit(std::string number, char digit) {
        int last_idx = -1;
        int n = number.size();
        for (int i = 0; i < n; ++i) {
            if (number[i] == digit) {
                last_idx = i;
                if (i + 1 < n && number[i + 1] > digit) {
                    return number.substr(0, i) + number.substr(i + 1);
                }
            }
        }
        return number.substr(0, last_idx) + number.substr(last_idx + 1);
    }
};

class Solution {
    public String removeDigit(String number, char digit) {
        int lastIdx = -1;
        int n = number.length();
        for (int i = 0; i < n; i++) {
            if (number.charAt(i) == digit) {
                lastIdx = i;
                if (i + 1 < n && number.charAt(i + 1) > digit) {
                    return number.substring(0, i) + number.substring(i + 1);
                }
            }
        }
        return number.substring(0, lastIdx) + number.substring(lastIdx + 1);
    }
}

var removeDigit = function(number, digit) {
    let lastIdx = -1;
    const n = number.length;
    for (let i = 0; i < n; i++) {
        if (number[i] === digit) {
            lastIdx = i;
            if (i + 1 < n && number[i + 1] > digit) {
                return number.slice(0, i) + number.slice(i + 1);
            }
        }
    }
    return number.slice(0, lastIdx) + number.slice(lastIdx + 1);
};
